(() => {
  const apply = () => {
    const card = document.querySelector('[data-name="samsung t7 shield ssd portatil 1tb usb c"]');
    if (!card) return;
    const link = card.querySelector('.offer-button');
    if (link) link.href = 'https://amzn.to/4r8XqJ2';
    const art = card.querySelector('.product-art');
    if (art) {
      art.style.cssText = 'display:flex;align-items:center;justify-content:center;padding:0;background:#fff;overflow:hidden;';
      art.innerHTML = '<img src="data:image/jpeg;base64," alt="Samsung T7 Shield SSD Portátil 1TB" loading="lazy" style="max-width:72%;max-height:72%;object-fit:contain;display:block;margin:auto">';
      art.removeAttribute('aria-hidden');
      art.setAttribute('role','img');
      art.setAttribute('aria-label','Samsung T7 Shield SSD Portátil 1TB');
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();